import React from "react";
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from "react-router-dom";
import "./App.css";
import AuthPage from "./component/AuthPage";
import UserDashboard from "./component/UserDashboard";
import AdminLogin from "./component/AdminLogin";
import AdminDashboard from "./component/AdminDashboard";
import ParcelList from "./component/ParcelList";
import ParcelForm from "./component/ParcelForm";
import TrackParcel from "./component/TrackParcel";
import ContactSupport from "./component/ContactSupport";

function App() {
  return (
    <Router>
      <Layout />
    </Router>
  );
}

function Layout() {
  const location = useLocation();
  const hideTabs =
    location.pathname.startsWith("/user/dashboard") ||
    location.pathname.startsWith("/admin/dashboard");

  const isHome = location.pathname === "/";

  return (
    <div>
      {!hideTabs && (
        <div className="top-tabs">
          <Link to="/">Home</Link>
          <Link to="/user">User</Link>
          <Link to="/admin">Admin</Link>
          <Link to="/track">Track</Link>
          <Link to="/support">Support</Link>
        </div>
      )}

      <Routes>
        <Route
          path="/"
          element={
            <div style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              height: "90vh",
              background: "linear-gradient(to right, #e0eafc, #cfdef3)",
              padding: "20px",
              textAlign: "center"
            }}>
              <h1 style={{ fontSize: "3rem", color: "#2c3e50" }}>Welcome to RouteMax</h1>
              <p style={{ fontSize: "1.2rem", color: "#34495e", maxWidth: "600px" }}>
                Seamlessly manage, track, and deliver your parcels with ease. Log in as a User or Admin to get started.
              </p>
              <img
                src="/route-home.jpg"
                alt="Parcel Tracking Illustration"
                style={{ maxWidth: "80%", height: "auto", marginTop: "30px", borderRadius: "12px", boxShadow: "0 5px 20px rgba(0, 0, 0, 0.1)" }}
              />
            </div>
          }
        />
        <Route path="/user" element={<AuthPage />} />
        <Route path="/user/dashboard" element={<UserDashboard />} />
        <Route path="/admin" element={<AdminLogin />} />
        <Route path="/admin/dashboard" element={<AdminDashboard />} />
        <Route path="/parcels" element={<ParcelList />} />
        <Route path="/parcels/new" element={<ParcelForm />} />
        <Route path="/parcels/edit/:id" element={<ParcelForm />} />
        <Route path="/track" element={<TrackParcel />} />
        <Route path="/support" element={<ContactSupport />} />
      </Routes>
    </div>
  );
}

export default App;
